const topics=[
{ne:'पाइल्स',en:'Piles',dn:'मलद्वार वरिपरि सुन्निएका रक्तनसा।',de:'Swollen blood vessels around the anus.',sn:'चिलाउने, गाँठो महसुस हुने वा दिसापछि रगत देखिने हुन सक्छ।',se:'Possible symptoms include itching, a lump or blood after passing stool.',an:'रक्तस्रावको कारण पाइल्स नै हो भनेर अनुमान नगर्नुहोस्। रक्तस्राव वा लगातार लक्षण भए जाँच गराउनुहोस्।',ae:'Do not assume bleeding is caused by piles. Arrange an assessment for bleeding or persistent symptoms.'},
{ne:'फिसर',en:'Anal fissure',dn:'मलद्वारको छालामा सानो चिरा।',de:'A small tear in the skin at the opening of the anus.',sn:'दिसा गर्दा तीखो दुखाइ र त्यसपछि पोल्ने वा रगत देखिने हुन सक्छ।',se:'Possible symptoms include sharp pain during a bowel movement, burning afterwards or bleeding.',an:'लक्षण बढे वा सुधार नभए चिकित्सकलाई भेट्नुहोस्। पर्याप्त पानी र फाइबरले दिसा नरम राख्न मद्दत गर्न सक्छ; आफ्नो स्वास्थ्य अवस्थाअनुसार सल्लाह लिनुहोस्।',ae:'See a clinician if symptoms worsen or do not improve. Fluids and dietary fibre can help keep stools soft; ask for advice appropriate to your health needs.'},
{ne:'फिस्टुला',en:'Anal fistula',dn:'आन्द्राको अन्तिम भाग र मलद्वार नजिकको छालाबीच बनेको सानो मार्ग।',de:'A small tunnel between the end of the bowel and skin near the anus.',sn:'लगातार दुखाइ, पीप वा दुर्गन्धयुक्त स्राव हुन सक्छ।',se:'Possible symptoms include persistent pain, pus or smelly discharge.',an:'लगातार स्राव वा दुखाइ भए जाँच गराउनुहोस्। तीव्र दुखाइसँग ज्वरो भए तत्काल सहायता लिनुहोस्।',ae:'Arrange an assessment for persistent discharge or pain. Seek urgent care for severe pain with fever.'},
{ne:'भेरिकोज भेन',en:'Varicose veins',dn:'प्रायः खुट्टामा देखिने फुलेका वा बाङ्गिएका नसा।',de:'Enlarged, twisted veins, usually in the legs.',sn:'दुखाइ, भारीपन, सुन्निने वा चिलाउने हुन सक्छ।',se:'Possible symptoms include aching, heaviness, swelling or itching.',an:'दुखाइ, सुन्निने, बिग्रँदै गएको अवस्था वा नभरिएको घाउ भए जाँच गराउनुहोस्। नसाबाट रक्तस्राव भए तत्काल स्वास्थ्य सेवा लिनुहोस्।',ae:'Arrange an assessment for pain, swelling, worsening symptoms or a wound that is not healing. Seek urgent care if a vein bleeds.'}
];let current=0;const language=document.getElementById('language');function lang(){return document.documentElement.lang==='ne'?'ne':'en'}function render(){const l=lang();document.querySelector('.tabs').innerHTML=topics.map((t,i)=>`<button type="button" role="tab" aria-selected="${i===current}" aria-controls="topic" id="tab-${i}" data-topic="${i}">${t[l]}</button>`).join('');const t=topics[current];document.getElementById('topic').setAttribute('aria-labelledby',`tab-${current}`);document.getElementById('topic').innerHTML=`<div><h3>${t[l]}</h3><p>${l==='ne'?t.dn:t.de}</p><p>${l==='ne'?t.sn:t.se}</p></div><div><h3>${l==='ne'?'अर्को कदम':'Your next step'}</h3><p>${l==='ne'?t.an:t.ae}</p></div>`;language.textContent=l==='ne'?'English ↗':'नेपाली ↗'}document.querySelector('.tabs').addEventListener('click',e=>{const b=e.target.closest('[data-topic]');if(b){current=Number(b.dataset.topic);render()}});document.querySelector('.tabs').addEventListener('keydown',e=>{if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();current=(current+(e.key==='ArrowRight'?1:3))%4;render();document.getElementById(`tab-${current}`).focus()}});language.addEventListener('click',()=>{document.documentElement.lang=lang()==='ne'?'en':'ne';render()});document.getElementById('download').addEventListener('click',()=>{const l=lang();const title=l==='ne'?'दीपसारा — बिरामी मार्गदर्शन':'Deepsara — Patient guide';const sections=topics.map(t=>`<h2>${t[l]}</h2><p>${l==='ne'?t.dn:t.de}</p><p>${l==='ne'?t.sn:t.se}</p><p>${l==='ne'?t.an:t.ae}</p>`).join('');const warning=document.querySelector('.warning').innerText;const prepare=l==='ne'?'परामर्शअघि लक्षण सुरु भएको समय, औषधि र एलर्जीको सूची, पुराना रिपोर्ट र आफ्ना प्रश्न तयार गर्नुहोस्।':'Before your consultation: prepare your symptom timeline, medicine and allergy list, previous reports and questions about options, risks, costs and recovery.';const data=`<!doctype html><html lang="${l}"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${title}</title><style>body{font-family:Arial,sans-serif;max-width:760px;margin:40px auto;padding:25px;color:#163f3a;line-height:1.8}h1,h2{line-height:1.4}aside{background:#fff0e2;padding:20px}button{padding:12px 20px}@media print{button{display:none}}</style><h1>${title}</h1><p>${l==='ne'?'सामान्य शैक्षिक जानकारी; चिकित्सकीय जाँचको विकल्प होइन।':'General educational information; not a substitute for a medical examination.'}</p><button onclick="window.print()">${l==='ne'?'प्रिन्ट / PDF सेभ':'Print / Save as PDF'}</button>${sections}<aside>${warning}</aside><h2>${l==='ne'?'परामर्शको तयारी':'Prepare for a consultation'}</h2><p>${prepare}</p><p>Sources: <a href="https://www.nhs.uk/symptoms/anal-pain/">NHS Anal pain</a>; <a href="https://www.nhs.uk/conditions/anal-fistula/">NHS Anal fistula</a>; <a href="https://www.nhs.uk/conditions/varicose-veins/">NHS Varicose veins</a></p><p>Updated 10 October 2026</p></html>`;const url=URL.createObjectURL(new Blob([data],{type:'text/html;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`deepsara-patient-guide-${l}.html`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)});render();
